function hexOk(c){return /^#[0-9a-f]{6}$/i.test(c||'')}
function luminancia(hex){const n=parseInt(hex.slice(1),16),f=v=>{v/=255;return v<=.03928?v/12.92:Math.pow((v+.055)/1.055,2.4)};return .2126*f(n>>16&255)+.7152*f(n>>8&255)+.0722*f(n&255)}
function aplicarFundo(cor){
  if(cor===undefined){const p=lsGet('qd_fundo')||'';cor=p==='padrao'?'':p||(S.cfg&&S.cfg.fundo)||''}
  const r=document.documentElement.style;
  if(!hexOk(cor)){['--bg','--colbg','--bgTxt','--bgMuted'].forEach(v=>r.removeProperty(v));document.documentElement.classList.remove('fundo-escuro');return}
  const escuro=luminancia(cor)<.18;
  r.setProperty('--bg',cor);
  // colunas acompanham o fundo: translúcidas sobre a cor escolhida, sempre legíveis
  r.setProperty('--colbg',`color-mix(in srgb,var(--panel) ${escuro?'86%':'62%'},${cor})`);
  r.setProperty('--bgTxt',escuro?'#F2F4F7':'#101828');r.setProperty('--bgMuted',escuro?'rgba(242,244,247,.75)':'#475467');
  document.documentElement.classList.toggle('fundo-escuro',escuro);
}
